import sys
def decode_runs(text):
    """Decode runs of decimal count followed by lowercase letter."""
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    result = []
    i = 0
    n = len(text)
    while i < n:
        # Parse the count (digits)
        if not text[i].isdigit():
            raise ValueError("Missing count")
        start = i
        while i < n and text[i].isdigit():
            i += 1
        count_str = text[start:i]
        if not count_str:
            raise ValueError("Missing count")
        count = int(count_str)
        if count == 0:
            raise ValueError("Zero count")
        # Parse the letter
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError("Missing or invalid letter")
        letter = text[i]
        i += 1
        # Append repeated letter
        result.append(letter * count)
    return ''.join(result)

def flatten(value):
    """
    Recursively flatten lists and tuples into a new list.
    All other values (including strings and dictionaries) are treated as atomic.
    """
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

