def path_normalize(path: str) -> str:
    """Normalize a POSIX path according to the specified rules."""
    absolute = path.startswith('/')
    parts = path.split('/')
    result = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if absolute:
                # Cannot go above absolute root
                if result:
                    result.pop()
                # else ignore
            else:
                # Relative path: resolve if possible, otherwise keep as '..'
                if result:
                    result.pop()
                else:
                    result.append('..')
        else:
            result.append(part)

    if absolute:
        if not result:
            return '/'
        else:
            return '/' + '/'.join(result)
    else:
        if not result:
            return '.'
        else:
            return '/'.join(result)

import heapq
from typing import Dict, List, Tuple, Optional, Any
def shortest(graph: Dict[Any, List[Tuple[Any, float]]],
             start: Any,
             end: Any) -> Optional[float]:
    """Return the shortest distance from start to end in a weighted graph.
    If start == end, distance is 0. If end is unreachable, return None.
    """
    if start == end:
        return 0

    # Initialize distances
    dist: Dict[Any, float] = {}
    dist[start] = 0

    # Priority queue: (distance, node)
    heap: List[Tuple[float, Any]] = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d != dist.get(u, float('inf')):
            continue  # outdated entry
        if u == end:
            break
        # Get neighbors; if u not in graph, treat as empty list
        neighbors = graph.get(u, [])
        for v, w in neighbors:
            if w < 0:
                raise ValueError("Edge weights must be nonnegative")
            new_dist = d + w
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))
            # Ensure v is in dist dict
            if v not in dist:
                dist[v] = float('inf')

    end_dist = dist.get(end, float('inf'))
    return None if end_dist == float('inf') else end_dist

def json_pointer(value, pointer):
    """
    Resolve a JSON Pointer (RFC6901) within a JSON value (dict or list).

    Args:
        value: The JSON value (dict, list, or any other type).
        pointer: A JSON Pointer string.

    Returns:
        The value pointed to by the pointer.

    Raises:
        ValueError: If the pointer is malformed, contains invalid escapes,
                    references a missing path, or uses a non‑canonical list index.
    """
    # Empty pointer returns the root value.
    if pointer == "":
        return value

    # Step 1: Decode '~1' -> '/' and '~0' -> '~' in that order.
    decoded_parts = []
    i = 0
    while i < len(pointer):
        if pointer[i] == "~":
            if i + 1 >= len(pointer):
                raise ValueError("Malformed escape in pointer")
            nxt = pointer[i + 1]
            if nxt == "0":
                decoded_parts.append("~")
                i += 2
            elif nxt == "1":
                decoded_parts.append("/")
                i += 2
            else:
                raise ValueError("Malformed escape in pointer")
        else:
            decoded_parts.append(pointer[i])
            i += 1
    decoded_pointer = "".join(decoded_parts)

    # Step 2: Split into tokens, handling leading slash.
    if decoded_pointer.startswith("/"):
        tokens = decoded_pointer.split("/")[1:]
    else:
        tokens = decoded_pointer.split("/")

    current = value
    for token in tokens:
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                raise ValueError(f"Path token '{token}' not found in dictionary")
        elif isinstance(current, list):
            # Validate canonical decimal representation.
            if not token.isdigit():
                raise ValueError(f"List index '{token}' is not a decimal integer")
            if token[0] == "0" and len(token) > 1:
                raise ValueError(f"List index '{token}' has leading zero")
            idx = int(token)
            if 0 <= idx < len(current):
                current = current[idx]
            else:
                raise ValueError(f"List index {idx} out of range")
        else:
            raise ValueError(f"Cannot resolve pointer token '{token}' into {type(current)}")

    return current

def stable_unique(values):
    """Return a list of values with duplicates removed, preserving first occurrence."""
    seen = set()
    result = []
    for v in values:
        key = _to_hashable(v)
        if key not in seen:
            seen.add(key)
            result.append(v)
    return result
def _to_hashable(obj):
    """Convert a JSON-compatible object into a hashable tuple."""
    if isinstance(obj, dict):
        # Sort items by key to ensure order-independent hashing
        return tuple((k, _to_hashable(v)) for k, v in sorted(obj.items(), key=lambda kv: kv[0]))
    elif isinstance(obj, list):
        return tuple(_to_hashable(item) for item in obj)
    else:
        # Assume other JSON-compatible types are hashable
        return obj

def parse_duration(text):
    """
    Parse a string of concatenated integer segments with units h, m, s into seconds.
    Units must appear in descending order, no repeats, no spaces, no signs.
    Empty or malformed input raises ValueError. Zero amounts are allowed.
    """
    if not text:
        raise ValueError("Empty input")

    unit_values = {'h': 3600, 'm': 60, 's': 1}
    priority = {'h': 3, 'm': 2, 's': 1}

    total = 0
    num_str = ''
    last_priority = None
    seen_units = set()

    for ch in text:
        if ch.isdigit():
            num_str += ch
        else:
            # must be a unit
            if not num_str:
                raise ValueError(f"Missing number before unit '{ch}'")
            num = int(num_str)
            if ch not in unit_values:
                raise ValueError(f"Invalid character '{ch}'")
            if ch in seen_units:
                raise ValueError(f"Repeated unit '{ch}'")
            cur_priority = priority[ch]
            if last_priority is not None and cur_priority > last_priority:
                raise ValueError(f"Units out of order: expected <= {last_priority}, got {ch}")
            total += num * unit_values[ch]
            seen_units.add(ch)
            last_priority = cur_priority
            num_str = ''

    # after processing all characters, any leftover digits?
    if num_str:
        raise ValueError(f"Missing unit after number '{num_str}'")

    return total

def expression(text):
    # Tokenize the input string into a list of tokens.
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and text[i].isdigit():
                i += 1
            num = int(text[start:i])
            tokens.append(('NUMBER', num))
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '*':
            tokens.append(('MULTIPLY', '*'))
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")
    tokens.append(('EOF', None))

    # Recursive descent parser.
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return ('EOF', None)

        def consume(self, expected_type=None):
            if self.pos >= len(self.tokens):
                raise ValueError("Unexpected end of input")
            token = self.tokens[self.pos]
            if expected_type is not None and token[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {token[0]}")
            self.pos += 1
            return token

        def parse_expression(self):
            left = self.parse_term()
            while True:
                token = self.peek()
                if token[0] == 'PLUS':
                    self.consume('PLUS')
                    right = self.parse_term()
                    left += right
                elif token[0] == 'MINUS':
                    self.consume('MINUS')
                    right = self.parse_term()
                    left -= right
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_factor()
            while True:
                token = self.peek()
                if token[0] == 'MULTIPLY':
                    self.consume('MULTIPLY')
                    right = self.parse_factor()
                    left *= right
                else:
                    break
            return left

        def parse_factor(self):
            token = self.peek()
            if token[0] == 'NUMBER':
                self.consume('NUMBER')
                return token[1]
            elif token[0] == 'PLUS':
                self.consume('PLUS')
                return self.parse_factor()  # unary plus
            elif token[0] == 'MINUS':
                self.consume('MINUS')
                return -self.parse_factor()  # unary minus
            elif token[0] == 'LPAREN':
                self.consume('LPAREN')
                value = self.parse_expression()
                if self.peek()[0] != 'RPAREN':
                    raise ValueError("Missing closing parenthesis")
                self.consume('RPAREN')
                return value
            else:
                raise ValueError(f"Unexpected token: {token}")

        def parse(self):
            result = self.parse_expression()
            if self.peek()[0] != 'EOF':
                raise ValueError("Unexpected tokens after expression")
            return result

    parser = Parser(tokens)
    return parser.parse()

def version_sort(versions):
    """
    Sort version strings numerically, ignoring trailing zero segments.
    """
    def key(version):
        # Split into integer parts
        parts = list(map(int, version.split('.')))
        # Strip trailing zeros
        while parts and parts[-1] == 0:
            parts.pop()
        return tuple(parts)

    # Python's sort is stable, so ties keep original order
    return sorted(versions, key=key)

def glob_match(pattern, text):
    """
    Returns True if pattern matches the entire text, False otherwise.
    Wildcards:
        '?'  matches any single character.
        '*'  matches any sequence of characters (including empty).
    All other characters are literal.
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(p_idx, t_idx):
        # If pattern is exhausted, text must also be exhausted
        if p_idx == len(pattern):
            return t_idx == len(text)

        # If text is exhausted, remaining pattern must be all '*'
        if t_idx == len(text):
            return all(pattern[i] == '*' for i in range(p_idx, len(pattern)))

        p_char = pattern[p_idx]

        if p_char == '*':
            # Match zero characters (skip '*') or match one more character
            return dp(p_idx + 1, t_idx) or dp(p_idx, t_idx + 1)
        elif p_char == '?' or p_char == text[t_idx]:
            # Match one character and move forward
            return dp(p_idx + 1, t_idx + 1)
        else:
            # Literal mismatch
            return False

    return dp(0, 0)

def memo_cycle(definitions, name):
    """
    Compute the value of `name` given a dictionary `definitions` where each key maps to either
    an integer or a list of dependency names. Dependencies are summed. Shared dependencies
    are counted each time they appear. Raises ValueError on cycles or missing dependencies.
    """
    memo = {}
    stack = set()

    def resolve(n):
        if n in memo:
            return memo[n]
        if n in stack:
            raise ValueError(f"Cycle detected involving {n}")
        stack.add(n)
        try:
            definition = definitions[n]
        except KeyError:
            raise ValueError(f"Missing definition for {n}")

        if isinstance(definition, int):
            value = definition
        else:
            # assume list of dependencies
            value = 0
            for dep in definition:
                if dep not in definitions:
                    raise ValueError(f"Missing dependency {dep}")
                value += resolve(dep)
        memo[n] = value
        stack.remove(n)
        return value

    return resolve(name)
